{
  "name": "mobtrackapp-clean",
  "slug": "mobtrackapp-clean",
  "version": "1.0.0",
  "orientation": "portrait",
  "icon": "./assets/icon.png",
  "userInterfaceStyle": "light",
  "newArchEnabled": true,
  "splash": {
    "image": "./assets/splash-icon.png",
    "resizeMode": "contain",
    "backgroundColor": "#ffffff"
  },
  "ios": {
    "supportsTablet": true
  },
  "android": {
    "adaptiveIcon": {
      "foregroundImage": "./assets/adaptive-icon.png",
      "backgroundColor": "#ffffff"
    },
    "edgeToEdgeEnabled": true,
    "predictiveBackGestureEnabled": false,
    "permissions": [
      "CAMERA",
      "FOREGROUND_SERVICE",
      "FOREGROUND_SERVICE_CAMERA",
      "FOREGROUND_SERVICE_MICROPHONE",
      "RECORD_AUDIO",
      "WAKE_LOCK",
      "android.permission.CAMERA",
      "android.permission.RECORD_AUDIO",
      "android.permission.FOREGROUND_SERVICE_MICROPHONE",
      "android.permission.WAKE_LOCK"
    ],
    "package": "com.punithpgowda.mobtrackappclean"
  },
  "web": {
    "favicon": "./assets/favicon.png"
  },
  "plugins": [
    [
      "expo-camera",
      {
        "cameraPermission": "Allow MobTrack to access your camera for silent capture."
      }
    ],
    [
      "expo-build-properties",
      {
        "android": {
          "kotlinVersion": "2.1.0"
        }
      }
    ]
  ],
  "backgroundColor": "#000000",
  "extra": {
    "eas": {
      "projectId": "db381ab8-29cc-4a17-a93f-ecb624ee79ed"
    }
  },
  "sdkVersion": "54.0.0",
  "platforms": [
    "ios",
    "android"
  ]
}
